const codigo = $input.first().json.codigo;
const rubrica = $input.first().json.rubrica;
const contexto = $input.first().json.contexto;

if (!codigo || !rubrica || !rubrica.criterios) {
  return [{ json: { error: "Faltan datos requeridos: codigo, rubrica, criterios" } }];
}

// Construir lista de criterios para el prompt (incluyendo IDs, subcriterios y evidencias)
let criteriosTexto = '';
for (const criterio of rubrica.criterios) {
  criteriosTexto += `- ID: ${criterio.id}\n  Nombre: ${criterio.nombre}\n  Peso: ${criterio.peso} pts\n  Descripción: ${criterio.descripcion}\n`;
  if (criterio.instrucciones_puntuacion) {
    criteriosTexto += `  Instrucciones de puntuación: ${criterio.instrucciones_puntuacion}\n`;
  }
  if (criterio.subcriterios && criterio.subcriterios.length > 0) {
    criteriosTexto += `  Evidencias esperadas (checklist verificable en la entrega):\n`;
    for (const sub of criterio.subcriterios) {
      if (sub.descripcion) criteriosTexto += `  - ${sub.descripcion}\n`;
      if (Array.isArray(sub.evidencias)) {
        for (const ev of sub.evidencias) {
          criteriosTexto += `    * ${ev}\n`;
        }
      }
    }
  }
  criteriosTexto += `\n`;
}

// Construir penalizaciones
let penalizacionesTexto = '';
if (rubrica.penalizaciones && rubrica.penalizaciones.length > 0) {
  for (const p of rubrica.penalizaciones) {
    penalizacionesTexto += `- ID: ${p.id}\n  Descripción: ${p.descripcion}\n  Descuento: ${p.descuento_porcentaje}%\n\n`;
  }
}

// Construir condiciones de desaprobación
let condicionesTexto = '';
if (rubrica.condiciones_desaprobacion && rubrica.condiciones_desaprobacion.length > 0) {
  for (const cd of rubrica.condiciones_desaprobacion) {
    condicionesTexto += `- ID: ${cd.id}\n  Condición: ${cd.condicion}\n  Nota máxima permitida: ${cd.nota_maxima ?? cd.nota_final ?? 0}\n\n`;
  }
}

// Construir contexto de metadata de la rúbrica (lenguaje, framework, formato, etc.)
let metadataTexto = '';
if (rubrica.metadata && typeof rubrica.metadata === 'object') {
  for (const [k, v] of Object.entries(rubrica.metadata)) {
    metadataTexto += `- ${k}: ${v}\n`;
  }
}

// Construir prompt completo
const prompt = `Eres un evaluador experto de trabajos prácticos de programación para la materia "${contexto.materia}".

Tu tarea es evaluar el siguiente código del alumno "${contexto.alumno}" según la rúbrica proporcionada.

## RÚBRICA DE EVALUACIÓN

Título: ${rubrica.titulo}
Tipo: ${rubrica.tipo}
Puntaje máximo: ${rubrica.puntaje_maximo}

Criterios:
${criteriosTexto}

## CONTEXTO ADICIONAL

${metadataTexto || 'Sin metadata adicional.'}

## PENALIZACIONES

Estas penalizaciones se aplican SOBRE el puntaje obtenido en los criterios. Evalúa si alguna aplica al código entregado.
${penalizacionesTexto || 'Ninguna definida.'}

## CONDICIONES DE DESAPROBACIÓN

IMPORTANTE: Estas condiciones establecen un TECHO (nota máxima) para la calificación. Si CUALQUIERA de ellas se cumple, la nota final NO PUEDE SUPERAR el máximo indicado. La nota final será el MÍNIMO entre la suma de criterios y la nota máxima de la condición. Evalúa cada condición cuidadosamente.
${condicionesTexto || 'Ninguna definida.'}

## CÓDIGO DEL ALUMNO

\`\`\`
${codigo}
\`\`\`

## INSTRUCCIONES DE EVALUACIÓN

1. Primero, evalúa cada criterio de la rúbrica normalmente (puntaje y feedback), verificando las evidencias esperadas de cada criterio contra el código entregado.
2. Luego, verifica si alguna CONDICIÓN DE DESAPROBACIÓN se cumple:
${rubrica.condiciones_desaprobacion ? rubrica.condiciones_desaprobacion.map(cd => `   - ${cd.id}: ${cd.condicion} → Si se cumple, nota máxima = ${cd.nota_maxima ?? cd.nota_final ?? 0}`).join('\n') : '   Ninguna.'}
3. Luego, verifica si alguna PENALIZACIÓN aplica:
${rubrica.penalizaciones ? rubrica.penalizaciones.map(p => `   - ${p.id}: ${p.descripcion} → Descuento del ${p.descuento_porcentaje}% sobre la nota`).join('\n') : '   Ninguna.'}
4. Calcula la nota final:
   - Calcula nota_antes_penalizaciones = suma de puntajes de los criterios.
   - Si aplica alguna condición de desaprobación → nota = min(nota_antes_penalizaciones, nota_maxima_de_la_condicion). Es decir, la nota no puede superar el techo.
   - Si aplica alguna penalización → aplica el descuento porcentual sobre nota_antes_penalizaciones.
   - Si no aplica nada → nota = nota_antes_penalizaciones.

Para cada criterio:
1. DEBES incluir el ID exacto del criterio de la rúbrica
2. Asigna un puntaje entre 0 y el peso del criterio
3. Determina el estado:
   - "OK" si logra ≥80% del peso del criterio
   - "WARNING" si logra 40-79% del peso
   - "ERROR" si logra <40% del peso
4. Proporciona feedback específico y constructivo

Además:
- Lista 2-4 fortalezas del código (array de strings)
- Lista 2-4 recomendaciones de mejora específicas (array de strings)
- Escribe un comentario general de 2-3 oraciones

## FORMATO DE RESPUESTA OBLIGATORIO

Responde ÚNICAMENTE con un JSON válido con esta estructura exacta:

{
  "nota": <número entre 0 y ${rubrica.puntaje_maximo}>,
  "condicion_desaprobacion_aplicada": <null si no aplica, o el ID de la condición que aplica (ej: "CD1")>,
  "penalizaciones_aplicadas": [<array de IDs de penalizaciones aplicadas, vacío si ninguna>],
  "nota_antes_penalizaciones": <número: suma de criterios antes de aplicar condiciones o penalizaciones>,
  "criterios": [
    {
      "id": "<ID exacto del criterio de la rúbrica>",
      "nombre": "<nombre exacto del criterio de la rúbrica>",
      "puntaje_obtenido": <número>,
      "puntaje_maximo": <número igual al peso del criterio>,
      "estado": "<OK|WARNING|ERROR>",
      "feedback": "<feedback específico>"
    }
  ],
  "fortalezas": ["<fortaleza 1>", "<fortaleza 2>"],
  "recomendaciones": ["<recomendación 1>", "<recomendación 2>"],
  "comentario_general": "<comentario de 2-3 oraciones>"
}

IMPORTANTE:
- CADA criterio debe tener su ID exacto de la rúbrica
- Si aplica una condición de desaprobación, "nota" debe ser min(suma_criterios, nota_maxima_de_la_condicion), pero IGUAL debes evaluar todos los criterios con su puntaje real para dar feedback
- Si aplica una penalización, "nota" debe reflejar el descuento aplicado sobre "nota_antes_penalizaciones"
- Si no aplica ni condición ni penalización, "nota" = "nota_antes_penalizaciones" = suma de puntajes
- Cada criterio de la rúbrica debe aparecer en la respuesta
- NO incluyas texto antes o después del JSON`;

// Construir body para Gemini API
const body = {
  generationConfig: {
    temperature: 0,
    topK: 1,
    topP: 1,
    candidateCount: 1,
    responseMimeType: "application/json",
    responseSchema: {
      type: "object",
      properties: {
        nota: { type: "number" },
        condicion_desaprobacion_aplicada: { type: "string", nullable: true },
        penalizaciones_aplicadas: {
          type: "array",
          items: { type: "string" }
        },
        nota_antes_penalizaciones: { type: "number" },
        criterios: {
          type: "array",
          items: {
            type: "object",
            properties: {
              id: { type: "string" },
              nombre: { type: "string" },
              puntaje_obtenido: { type: "number" },
              puntaje_maximo: { type: "number" },
              estado: { type: "string", enum: ["OK", "WARNING", "ERROR"] },
              feedback: { type: "string" }
            },
            required: ["id", "nombre", "puntaje_obtenido", "puntaje_maximo", "estado", "feedback"]
          }
        },
        fortalezas: {
          type: "array",
          items: { type: "string" }
        },
        recomendaciones: {
          type: "array",
          items: { type: "string" }
        },
        comentario_general: { type: "string" }
      },
      required: ["nota", "condicion_desaprobacion_aplicada", "penalizaciones_aplicadas", "nota_antes_penalizaciones", "criterios", "fortalezas", "recomendaciones", "comentario_general"]
    }
  },
  contents: [
    {
      role: "user",
      parts: [
        { text: prompt }
      ]
    }
  ]
};

return [{ json: { geminiBody: body } }];

// Parser de respuesta de Gemini

  const geminiResponse = $input.first().json;
  const startTime = Date.now();

  try {
    // Verificar si hay error de Gemini (503, 429, etc.)
    if (geminiResponse.error) {
      const errorMsg = geminiResponse.error.message || JSON.stringify(geminiResponse.error);
      const errorCode = geminiResponse.error.code || 'UNKNOWN';

      return [{
        json: {
          success: false,
          error: {
            code: "GEMINI_ERROR",
            message: `Error de Gemini [${errorCode}]: ${errorMsg}`,
            retry: errorCode === 503 || errorCode === 500
          }
        }
      }];
    }

    // Normalizar respuesta (puede venir como array o objeto)
    let responseArray;
    if (Array.isArray(geminiResponse)) {
      responseArray = geminiResponse;
    } else if (geminiResponse.body && Array.isArray(geminiResponse.body)) {
      responseArray = geminiResponse.body;
    } else if (geminiResponse.data && Array.isArray(geminiResponse.data)) {
      responseArray = geminiResponse.data;
    } else {
      responseArray = [geminiResponse];
    }

    const candidate = responseArray[0]?.candidates?.[0];

    if (!candidate) {
      return [{
        json: {
          success: false,
          error: {
            code: "PARSING_ERROR",
            message: "No se encontró candidate en respuesta de Gemini",
            retry: true
          }
        }
      }];
    }

    const textContent = candidate.content?.parts?.[0]?.text;

    if (!textContent) {
      return [{
        json: {
          success: false,
          error: {
            code: "PARSING_ERROR",
            message: "No se encontró texto en la respuesta",
            retry: true
          }
        }
      }];
    }

    // Parsear el JSON que viene como string
    const parsedData = JSON.parse(textContent);

    // Validar estructura mínima
    if (!parsedData.nota && parsedData.nota !== 0) {
      return [{
        json: {
          success: false,
          error: {
            code: "PARSING_ERROR",
            message: "Respuesta no contiene campo 'nota'",
            retry: true
          }
        }
      }];
    }

    if (!Array.isArray(parsedData.criterios)) {
      return [{
        json: {
          success: false,
          error: {
            code: "PARSING_ERROR",
            message: "Respuesta no contiene 'criterios' como array",
            retry: true
          }
        }
      }];
    }

    // Validación de consistencia
    const sumaCriterios = parsedData.criterios.reduce((sum, c) => sum + (c.puntaje_obtenido || 0), 0);

    // Siempre asegurar que nota_antes_penalizaciones refleje la suma real de criterios
    parsedData.nota_antes_penalizaciones = sumaCriterios;

    // Si hay condición de desaprobación, la nota es min(sumaCriterios, techo)
    if (parsedData.condicion_desaprobacion_aplicada) {
      if (parsedData.nota > sumaCriterios) {
        parsedData.nota = sumaCriterios;
      }
    }

    // Si no hay ni condiciones ni penalizaciones, la nota debe ser la suma
    if (!parsedData.condicion_desaprobacion_aplicada &&
        (!parsedData.penalizaciones_aplicadas || parsedData.penalizaciones_aplicadas.length === 0)) {
      parsedData.nota = sumaCriterios;
    }

    // Construir metadata
    const elapsedTime = Date.now() - startTime;
    const metadata = {
      modelo: "gemini-2.5-flash",
      tokens_entrada: candidate.tokenCount?.totalTokens || 0,
      tokens_salida: candidate.tokenCount?.candidatesTokenCount || 0,
      tiempo_ms: elapsedTime
    };

    // Retornar resultado exitoso CON todos los campos de CD/penalizaciones
    return [{
      json: {
        success: true,
        correccion: {
          nota: parsedData.nota,
          nota_antes_penalizaciones: parsedData.nota_antes_penalizaciones,
          condicion_desaprobacion_aplicada: parsedData.condicion_desaprobacion_aplicada || null,
          penalizaciones_aplicadas: parsedData.penalizaciones_aplicadas || [],
          criterios: parsedData.criterios,
          fortalezas: parsedData.fortalezas || [],
          recomendaciones: parsedData.recomendaciones || [],
          comentario_general: parsedData.comentario_general || ""
        },
        metadata: metadata
      }
    }];

  } catch (error) {
    return [{
      json: {
        success: false,
        error: {
          code: "PARSING_ERROR",
          message: `Error al procesar corrección: ${error.message}`,
          retry: true
        }
      }
    }];
  }
